"""Source-only matrix preparation before any evaluator observation."""
from pathlib import Path
import json,hashlib,gzip
H=Path(__file__).resolve().parent;S=H.parent/'source-forward';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert not(H/'MATRIX.json').exists(),'never replace a predeclared cohort'
f=json.loads((S/'FROZEN.json').read_text());assert all(sha(S/k)==v for k,v in f['files'].items());pairs=json.loads((H.parent/'TWENTY_SOURCE_PAIRS.json').read_text())['pairs'];conditions=json.loads((H.parent/'CONDITIONS.json').read_text());assert len(pairs)==20 and {(p['startAnchorIndex'],p['goalAnchorIndex'])for p in pairs}=={(i,j)for i in range(5)for j in range(5)if i!=j}
(H/'plans').mkdir(exist_ok=False);ledger=json.loads((S/'results/LEDGER.json').read_text());plans=[]
for pair,row in zip(pairs,ledger):
 p=S/'results'/row['path'];assert sha(p)==row['sha256'];r=json.load(gzip.open(p,'rt'));assert r['pair']==pair and r['complete']and r['referenceInputUsed']is False
 plan={'pairIndex':pair['pairIndex'],'sourcePair':pair,'start':pair['startOriginalXYZ'],'goal':pair['goalOriginalXYZ'],'steeringGoalOriginalFrame':pair['goalOriginalXYZ'],'initialYawRadians':r['initialYawRadians'],'originalFramePath':r['points'],'legs':[{'originalTaskGoal':pair['goalOriginalXYZ'],'originalFramePath':r['points']}],'profile':'body45cmMargin0','geometry':{'width':.45,'depth':.30,'height':1.6,'margin':0.},'taskArrivalToleranceMetres':.35,'cornerConsumptionToleranceMetres':.01,'maximumTicks':2500,'sourceOnly':True,'physicalAuthority':False,'sourceQuerySHA256':row['sha256'],'sourceFloorEvaluationBoundsXYZ':r['sourceFloorEvaluationBoundsXYZ'],'sourceBodyCircleBoundsXZ':r['sourceBodyCircleBoundsXZ']}
 name=f"pair-{pair['pairIndex']:02d}.json";(H/'plans'/name).write_text(json.dumps(plan,indent=2)+'\n');plans.append({'pairIndex':pair['pairIndex'],'path':'plans/'+name,'sha256':sha(H/'plans'/name)})
(H/'CONDITIONS.json').write_bytes((H.parent/'CONDITIONS.json').read_bytes());episodes=[{'episodeIndex':5*p['pairIndex']+i,'pairIndex':p['pairIndex'],'conditionID':c['id'],'seed':72000+p['pairIndex'],'status':'notRun','movementExecuted':False}for p in pairs for i,c in enumerate(conditions['conditions'])]
m={'scope':'100 scheduled simulator outcomes, not100 guaranteed movements','sourceManifestSHA256':sha(S/'FROZEN.json'),'pairFileSHA256':sha(H.parent/'TWENTY_SOURCE_PAIRS.json'),'conditionsSHA256':sha(H/'CONDITIONS.json'),'pairs':pairs,'plans':plans,'episodes':episodes,'maximumTicksPerEpisode':2500,'episodeLimits':{'CPUSeconds':900,'wallSeconds':1200,'RSSBytes':int(3.5*1024**3),'outputBytes':10*1024**2},'cacheLimits':{'CPUSeconds':180,'wallSeconds':240,'RSSBytes':int(3.5*1024**3),'outputBytes':20*1024**2},'minimumAvailableRAMBytes':int(4.3*1024**3),'stageDiskCapBytes':4*1024**3,'physicalAuthority':False,'sourceQueriesChanged':False,'invalidStartsRemainInDenominator':True}
(H/'MATRIX.json').write_text(json.dumps(m,indent=2)+'\n');print(sha(H/'MATRIX.json'))
